@Test func openingUsesTheInjectedLocalDayAndPreservesTheConfirmedTime() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = try makeSavedProduct(in: context)
    let item = try makeSavedItem(in: context, product: product, status: .unopened)
    let original = ItemSnapshot(item)
    let now = Date(timeIntervalSince1970: 1_736_006_400)
    let opening = now.addingTimeInterval(9 * 3600)
    var saveCalls = 0
    let actions = ItemActions(context: context) { context in
        saveCalls += 1
        return Result { try context.save() }
    }

    guard
        case .failure(.validation(.futureOpeningDate)) = actions.open(
            item, openingDate: opening, now: now, calendar: try calendar(secondsFromGMT: 0)
        )
    else {
        Issue.record("UTCの翌日の開封が拒否されなかった")
        return
    }
    #expect(saveCalls == 0)
    #expect(ItemSnapshot(item) == original)
    #expect(!context.hasChanges)

    // 日本では同じ暦日なので、現在時刻より後の確認済み時刻もそのまま保存する。
    try actions.open(
        item, openingDate: opening, now: now, calendar: try calendar(secondsFromGMT: 9 * 3600)
    ).get()

    #expect(saveCalls == 1)
    #expect(item.status == .inUse)
    #expect(item.openingDate == opening)
    #expect(item.consumedDate == nil)
    #expect(item.updatedAt == now)
    #expect(!context.hasChanges)
    let reader = ModelContext(container)
    #expect(ItemSnapshot(try #require(reader.fetch(FetchDescriptor<Item>()).first)) == ItemSnapshot(item))
}

@State private var openingDate: Date
@State private var latestOpeningDate: Date
@State private var saveError: ItemActions.ActionError?

private let confirm: @MainActor (Date, Calendar) -> Result<Void, ItemActions.ActionError>

init(confirm: @escaping @MainActor (Date, Calendar) -> Result<Void, ItemActions.ActionError>) {
    let now = Date.now
    _openingDate = State(initialValue: now)
    _latestOpeningDate = State(initialValue: now)
    self.confirm = confirm
}

    DatePicker("開封日", selection: $openingDate, in: ...latestOpeningDate, displayedComponents: .date)
        .datePickerStyle(.wheel)
        .accessibilityIdentifier("item-open-date")
} header: {
    Text("開封日")

func open(
    _ item: Item, openingDate: Date, now: Date = Date(), calendar: Calendar = .current
) -> Result<Void, ActionError> {
    update(item) { item.open(on: openingDate, now: now, calendar: calendar) }
}

private func update(
    _ item: Item, change: () -> Result<Void, ItemRules.ValidationError>
) -> Result<Void, ActionError> {
    guard !context.hasChanges else {
        return .failure(.pendingChanges)
    }

    guard item.modelContext === context else {
        return .failure(.itemNotInContext)
    }

    switch change() {
    case .success:
        break
    case .failure(let error):
        return .failure(.validation(error))
    }

    switch save(context) {
    case .success:
        return .success(())
    case .failure(let error):
        context.rollback()
        return .failure(.persistence(error))
    }
}
